function DecorVendorData:GetVendorList() return self.Vendors end
function DecorVendorData:GetVendorsForMap(mapID, includeParent)
    local out = {}
    for _, vendor in ipairs(self.Vendors) do
        if vendor.mapID and vendor.x and vendor.y and (not mapID or vendor.mapID == mapID) then
            out[#out + 1] = vendor
        end
    end
    return out
end
function DecorVendorData:GetAchievementEntries() return self.AchievementEntries end
function DecorVendorData:GetQuestEntries() return self.QuestEntries end
function DecorVendorData:GetProfessionEntries() return self.ProfessionEntries end
function DecorVendorData:GetPreviewCount() local c=0 for _ in pairs(self.ModelPositions) do c=c+1 end return c end
function DecorVendorData:GetModelPosition(modelID) return self.ModelPositions[tonumber(modelID)] end